    await page.waitForTimeout(600);
    try {
      for (const st of sc.steps || []) {
        if (st.deliver) await page.evaluate(([t, p]) => window.fake.deliver(t, p), st.deliver);
        if (st.click) await page.locator(st.click).first().click({ timeout: 3000 });
        if (st.hover) await page.locator(st.hover).first().hover({ timeout: 3000 });
        if (st.fill) await page.locator(st.fill[0]).first().fill(st.fill[1]);
        if (st.eval) await page.evaluate(st.eval);
        await page.waitForTimeout(st.wait || 250);
      }
    } catch (e) { log.push(`${sc.id} step failed: ${e.message.split('\n')[0]}`); }
