#pragma once

// Where apps keep their per-user data, by platform.
//
// The rule is the one OrcaSlicer's GUI_App applies to its own default
// data_dir(): macOS ~/Library/Application Support/<name>, Windows
// %APPDATA%\<name>, Linux $XDG_CONFIG_HOME/<name> or ~/.config/<name>.
// GUI_App works it out inline through wxStandardPaths; this is the same rule
// in plain std, so files compiled into the GUI-free test binaries can use it.

#include <filesystem>
#include <string>

namespace Slic3r::GUI::JusPrin {

struct UserFolders
{
    std::filesystem::path home;
    // The folder apps keep their data folders in.
    std::filesystem::path app_data;
};

// From the environment: HOME (USERPROFILE on Windows), APPDATA, XDG_CONFIG_HOME.
UserFolders user_folders();

// Where the app called `name` keeps its data when it runs on its default
// folder, whatever folder this app was started with.
std::filesystem::path default_app_folder(const std::string& name);

// The data folder of another app installed here, as first launch looks for
// it: the value of `override_variable` when set, empty (none) when it is set
// to "", and default_app_folder(name) when it is unset. Test runs set the
// variable so they never read the person's real installs.
std::filesystem::path installed_app_folder(const std::string& name, const char* override_variable);

} // namespace Slic3r::GUI::JusPrin

#include "AppFolders.hpp"

#include <cstdlib>

namespace Slic3r::GUI::JusPrin {
namespace fs = std::filesystem;

namespace {
std::string env(const char* key)
{
    const char* value = std::getenv(key);
    return value ? value : "";
}
} // namespace

UserFolders user_folders()
{
    UserFolders folders;
#ifdef _WIN32
    const auto profile = env("USERPROFILE");
    folders.home = profile.empty() ? fs::current_path() : fs::u8path(profile);
    const auto appdata = env("APPDATA");
    folders.app_data = appdata.empty() ? folders.home : fs::u8path(appdata);
#elif defined(__APPLE__)
    const auto home = env("HOME");
    folders.home = home.empty() ? fs::current_path() : fs::u8path(home);
    folders.app_data = folders.home / "Library" / "Application Support";
#else
    const auto home = env("HOME");
    folders.home = home.empty() ? fs::current_path() : fs::u8path(home);
    const auto xdg = env("XDG_CONFIG_HOME");
    folders.app_data = xdg.empty() ? folders.home / ".config" : fs::u8path(xdg);
#endif
    return folders;
}

fs::path default_app_folder(const std::string& name) { return user_folders().app_data / fs::u8path(name); }

fs::path installed_app_folder(const std::string& name, const char* override_variable)
{
    if (const char* chosen = std::getenv(override_variable))
        return fs::u8path(chosen);
    return default_app_folder(name);
}

} // namespace Slic3r::GUI::JusPrin

