// v1's version number stays behind too. OrcaSlicer reads it as the version
// these settings were last saved by, and for anything older than 2.4.0 it
// opens a notice about moving profile sync from Bambu Cloud to Orca Cloud,
// over the welcome-back window. Without it the settings read as new.
json carried_settings(json settings)
{
    if (!settings.is_object())
        return settings;
    settings.erase("jusprin_server");
    if (auto app = settings.find("app"); app != settings.end() && app->is_object())
        app->erase("version");
    return settings;
}

input.new_string:
// v1's version number is replaced by this app's, the one OrcaSlicer writes
// there at every launch. OrcaSlicer reads it as the version these settings
// were last saved by, and for anything older than 2.4.0 it opens a notice
// about moving profile sync from Bambu Cloud to Orca Cloud, over the
// welcome-back window. Erasing it instead would turn auto-backup back on.
json carried_settings(json settings)
{
    if (!settings.is_object())
        return settings;
    settings.erase("jusprin_server");
    if (auto app = settings.find("app"); app != settings.end() && app->is_object())
        (*app)["version"] = SoftFever_VERSION;
    return settings;
}

